import Foundation

/// A user-visible string of the String Catalog (`Resources/Localizable.xcstrings`), by its name in DELOS for
/// Android's string resources. The catalog is generated by tools/l10n/import_android.py; tools/l10n/check_usage.py
/// checks that every name used here is in it with all ten languages.
func L(_ name: String) -> String {
    String(localized: String.LocalizationValue(name), bundle: .module)
}

/// A catalog string with arguments, formatted for the current locale.
func L(_ name: String, _ arguments: any CVarArg...) -> String {
    String(format: L(name), locale: .current, arguments: arguments)
}

/// A catalog plural whose forms carry no number (Android's `getQuantityString` of "hour" / "hours"): the form for
/// [count] in the current language.
func LPlural(_ name: String, _ count: Int) -> String {
    String.localizedStringWithFormat(Bundle.module.localizedString(forKey: name, value: nil, table: nil), count)
}
